// Launchers of the compiled contracter kernels, one explicit instantiation
// per table in its own translation unit (generated by CMake from
// MOLNEX_CT_CONFIGS).
#pragma once

#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>

#include "contracter_compiled.cuh"

namespace molnex::equivariance::ct {

struct Args {
  at::Tensor x1, x2, w, index;     // (E, NS1·U), (N, NS2·U), (NB·U,), (E,) int32
  at::Tensor g, dgx1, dgx2, dgw;   // adjoints
  at::Tensor out_y;                // forward (E, NO·U)
  at::Tensor out_1, out_2, out_g;  // gx1 / dx1 (E, NS1·U), gx2 / dx2 per edge (E, NS2·U), dg (E, NO·U)
  at::Tensor partial;              // (parts, NB·U)
  at::ArrayRef<double> values;
  int64_t channels, tile, parts, chunk;
};

template <typename T, int ID>
Coefficients<T, Table<ID>::NT> pack_values(at::ArrayRef<double> values) {
  constexpr int NT = Table<ID>::NT;
  TORCH_CHECK(values.size() == size_t(NT), "the compiled table has ", NT, " terms, got ",
              values.size(), " coefficients");
  Coefficients<T, NT> c;
  for (int t = 0; t < NT; ++t) c.c[t] = T(values[t]);
  return c;
}

template <int ID>
void run_forward(const Args& a) {
  AT_DISPATCH_FLOATING_TYPES(a.x1.scalar_type(), "ct_forward", [&] {
    const auto coef = pack_values<scalar_t, ID>(a.values);
    forward_kernel<scalar_t, ID>
        <<<unsigned(a.parts), unsigned(a.tile), 0, at::cuda::getCurrentCUDAStream()>>>(
            a.x1.const_data_ptr<scalar_t>(), a.x2.const_data_ptr<scalar_t>(),
            a.w.const_data_ptr<scalar_t>(), a.index.const_data_ptr<int32_t>(),
            a.out_y.mutable_data_ptr<scalar_t>(), a.x1.size(0), a.x2.size(0), a.channels, a.chunk, coef);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
  });
}

template <int ID>
void run_first(const Args& a) {
  AT_DISPATCH_FLOATING_TYPES(a.x1.scalar_type(), "ct_first", [&] {
    const auto coef = pack_values<scalar_t, ID>(a.values);
    const auto stream = at::cuda::getCurrentCUDAStream();
    first_rows_kernel<scalar_t, ID><<<unsigned(a.parts), unsigned(a.tile), 0, stream>>>(
        a.x1.const_data_ptr<scalar_t>(), a.x2.const_data_ptr<scalar_t>(), a.w.const_data_ptr<scalar_t>(),
        a.index.const_data_ptr<int32_t>(), a.g.const_data_ptr<scalar_t>(),
        a.out_1.mutable_data_ptr<scalar_t>(), a.out_2.mutable_data_ptr<scalar_t>(), a.x1.size(0),
        a.x2.size(0), a.channels, a.chunk, coef);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    weight_kernel<scalar_t, ID, false><<<unsigned(a.parts), unsigned(a.tile), 0, stream>>>(
        a.x1.const_data_ptr<scalar_t>(), a.x2.const_data_ptr<scalar_t>(), a.index.const_data_ptr<int32_t>(),
        a.g.const_data_ptr<scalar_t>(), nullptr, nullptr, a.partial.mutable_data_ptr<scalar_t>(),
        a.x1.size(0), a.x2.size(0), a.channels, a.chunk, coef);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
  });
}

template <int ID>
void run_second(const Args& a) {
  AT_DISPATCH_FLOATING_TYPES(a.x1.scalar_type(), "ct_second", [&] {
    const auto coef = pack_values<scalar_t, ID>(a.values);
    const auto stream = at::cuda::getCurrentCUDAStream();
    second_rows_kernel<scalar_t, ID><<<unsigned(a.parts), unsigned(a.tile), 0, stream>>>(
        a.x1.const_data_ptr<scalar_t>(), a.x2.const_data_ptr<scalar_t>(), a.w.const_data_ptr<scalar_t>(),
        a.index.const_data_ptr<int32_t>(), a.g.const_data_ptr<scalar_t>(),
        a.dgx1.const_data_ptr<scalar_t>(), a.dgx2.const_data_ptr<scalar_t>(),
        a.dgw.const_data_ptr<scalar_t>(), a.out_1.mutable_data_ptr<scalar_t>(),
        a.out_2.mutable_data_ptr<scalar_t>(), a.out_g.mutable_data_ptr<scalar_t>(), a.x1.size(0),
        a.x2.size(0), a.channels, a.chunk, coef);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    weight_kernel<scalar_t, ID, true><<<unsigned(a.parts), unsigned(a.tile), 0, stream>>>(
        a.x1.const_data_ptr<scalar_t>(), a.x2.const_data_ptr<scalar_t>(), a.index.const_data_ptr<int32_t>(),
        a.g.const_data_ptr<scalar_t>(), a.dgx1.const_data_ptr<scalar_t>(),
        a.dgx2.const_data_ptr<scalar_t>(), a.partial.mutable_data_ptr<scalar_t>(), a.x1.size(0),
        a.x2.size(0), a.channels, a.chunk, coef);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
  });
}

#define MOLNEX_CT_DECLARE(ID)                           \
  extern template void run_forward<ID>(const Args&);    \
  extern template void run_first<ID>(const Args&);      \
  extern template void run_second<ID>(const Args&);
MOLNEX_CT_CONFIGS(MOLNEX_CT_DECLARE)
#undef MOLNEX_CT_DECLARE

}  // namespace molnex::equivariance::ct
